46	function getCacheInstance() {
47	  if (!cacheInstance) {
48	    let cachePath = '';
49	    const stores = [];
50	
51	    if (cacheType === 'disk' && enabled) {
52	      cachePath =
53	        getEnvString('PROMPTFOO_CACHE_PATH') || path.join(getConfigDirectoryPath(), 'cache');
54	
55	      if (!fs.existsSync(cachePath)) {
56	        logger.info(`Creating cache folder at ${cachePath}.`);
57	        fs.mkdirSync(cachePath, { recursive: true });
58	      }
59	
60	      const newCacheFile = path.join(cachePath, 'cache.json');
61	
62	      try {
63	        const store = new KeyvFile({
64	          filename: newCacheFile,
65	        });
66	
67	        const keyv = new Keyv({
68	          store,
69	          ttl: getCacheTtlMs(),
70	        });
71	
72	        stores.push(keyv);
