52	export function parseAzureModerationResponse(
53	  data: AzureAnalyzeTextResult,
54	): ProviderModerationResponse {
55	  try {
56	    logger.debug(`Azure Content Safety API response: ${JSON.stringify(data)}`);
57	
58	    if (!data) {
59	      logger.error('Azure Content Safety API returned invalid response: null or undefined');
60	      return { flags: [] };
61	    }
62	
63	    const categories = data.categoriesAnalysis || [];
64	    const blocklistMatches =
65	      data.blocklistsMatch || (data as any).blocklistsMatch || (data as any).blocklists_match || [];
66	
67	    if (!categories || categories.length === 0) {
68	      return { flags: [] };
69	    }
70	
71	    const flags: ModerationFlag[] = [];
72	
73	    for (const analysis of categories) {
74	      if (analysis.severity > 0) {
75	        const confidence = analysis.severity / 7;
76	
77	        flags.push({
78	          code: analysis.category.toLowerCase(),
79	          description: `Content flagged for ${analysis.category}`,
80	          confidence,
81	        });
82	      }
83	    }
84	
85	    for (const match of blocklistMatches || []) {
86	      flags.push({
87	        code: `blocklist:${match.blocklistName}`,
88	        description: `Content matched blocklist item: ${match.blocklistItemText}`,
89	        confidence: 1.0,
90	      });
91	    }
92	
93	    return { flags };
94	  } catch (error) {
95	    logger.error(`Error parsing Azure Content Safety API response: ${error}`);
96	    return { flags: [], error: 'Failed to parse moderation response' };
